from lib import *
S = SS('g54')
steps = [
    step("metrics.All() 在 Go 1.27.1(arm64 macOS)上共 107 个指标:累计型 75 个;按取值类型 uint64 87 个、float64 12 个、直方图 8 个。按第一段路径分:/cgo 1 个、/cpu 11 个、/gc 26 个、/godebug 41 个、/memory 14 个、/sched 13 个、/sync 1 个。/sched 下有 goroutines、goroutines/runnable、goroutines/waiting、goroutines-created、threads/total,以及 latencies 和四个 pauses 直方图。", t=tl(S(1)), done=lidx(S(1), 'metrics.All() 共 107', '按第一段路径分组'), mark=lidx(S(1), '/sched/latencies:seconds', '/sched/goroutines-created'), b=bars([['/godebug', 41, '41'], ['/gc', 26, '26'], ['/memory', 14, '14'], ['/sched', 13, '13'], ['/cpu', 11, '11']], 41, done=[0, 1], mark=[3]), kv=KV([['指标总数', '107(累计型 75)'], ['类型', 'uint64 87 / float64 12 / 直方图 8'], ['最多的一组', '/godebug 41 个']], ['最多的一组'])),
    step("读一个不存在的指标名不会报错也不会 panic:Kind=0,正是 KindBad;同一次 Read 里存在的指标(/gc/cycles/total:gc-cycles)Kind=1(uint64),值为 0。", t=tl(S(2)), mark=lidx(S(2), 'Kind=0'), kv=KV([['不存在的指标', 'Kind=0 = KindBad'], ['同一次 Read 的其它指标', '照常读到'], ['用法', '读完先检查 Kind']], ['用法'])),
    step("对账:分配 100 个 1MiB 切片并 GC 一次之后,/gc/heap/allocs:bytes 增加 104913992,与 MemStats.TotalAlloc 增加量相同;/gc/heap/allocs:objects 增加 331,与 Mallocs 相同;/gc/cycles/total:gc-cycles = 7 = NumGC;/memory/classes/total:bytes = 118708504 = MemStats.Sys。唯一对不上的是 /sched/goroutines:goroutines = 66,而 runtime.NumGoroutine() = 51。", t=tl(S(3)), done=lidx(S(3), '/gc/heap/allocs:bytes', '/gc/heap/allocs:objects', '/gc/cycles/total', '/memory/classes/total'), mark=lidx(S(3), 'NumGoroutine() = 51'), kv=KV([['allocs / Mallocs / NumGC / Sys', '和 MemStats 逐字节一致'], ['goroutines', '66 对 51,差 15'], ['原因(见第六节源码)', '指标按 gcount(true),NumGoroutine 按 gcount(false)']], ['goroutines'])),
    step("读一次指标的成本(复用切片):metrics.Read 读 1 个指标 188 ns,0 次分配;读全部 107 个指标 1934 ns,0 次分配;runtime.ReadMemStats 22760 ns,0 次分配。", t=tl(S(4)), mark=lidx(S(4), 'Read(1 个指标', 'Read(全部', 'ReadMemStats'), b=bars([['Read 1 个指标(ns)', 188, '188'], ['Read 全部 107 个指标', 1934, '1934'], ['ReadMemStats', 22760, '22760']], 22760, done=[0, 1], mark=[2]), kv=KV([['读 1 个', '188 ns'], ['读全部 107 个', '1934 ns'], ['ReadMemStats', '22760 ns']], ['读全部 107 个'])),
    step("直方图指标:GOMAXPROCS=1,200 个各自计算约 3 毫秒的 goroutine 同时就绪。/sched/latencies:seconds(goroutine 在可运行状态等待上 CPU 的时间)共 162 个桶、一共只记录了 23 次(为什么不是 200 次我没有查)。p50 落在 [0.0838861 s, 0.100663 s),p90 落在 [0.134218 s, 0.167772 s),p99 和最大落在 [0.167772 s, 0.201327 s)。", t=tl(S(5)), done=lidx(S(5), 'p50', 'p90'), mark=lidx(S(5), 'p99', '最大', '162 个桶'), b=bars([['p50 桶下界(ms)', 83.9, '≈84'], ['p90 桶下界', 134.2, '≈134'], ['p99/最大 桶下界', 167.8, '≈168']], 167.8, done=[0], mark=[1, 2]), kv=KV([['桶数', '162'], ['记录次数', '23(原因未查)'], ['p99 / 最大', '约 168–201 ms']], ['p99 / 最大'])),
    step("文档与源码:go doc runtime/metrics 说,鼓励用户对 All 返回的指标采样,以便跨版本兼容;指标的 kind “is guaranteed not to change”;包承诺 never produce NaN 或无穷大的浮点值。/sched/latencies:seconds 的说明是“goroutine 在调度器里处于可运行状态、真正开始运行之前的时间分布”。源码:runtime.NumGoroutine 是 gcount(false),/sched/goroutines 指标的 gTotal 是 gcount(true)——所以指标多出的 15 个是系统 goroutine。", t=tl(S(6)), done=lidx(S(6), 'Thus, users of this API', 'guaranteed not to change', 'never produce'), mark=lidx(S(6), 'Distribution of the time goroutines', 'gcount(false)', 'gcount(true)'), kv=KV([['兼容性', 'kind 保证不变;指标可能被弃用'], ['浮点值', '不会出现 NaN 与无穷大'], ['66 对 51', 'gcount(true) 对 gcount(false)']], ['66 对 51'])),
]
A = mkartg('g54', 54, 'Go,runtime/metrics,指标,可观测性,真实验证,动画演示',
    '在 Go 1.27.1 里实测 runtime/metrics:共 107 个指标(75 个累计型);分配字节数、GC 次数、Sys 与 MemStats 逐字节一致,goroutine 数 66 对 NumGoroutine 的 51(指标包含系统 goroutine);读 1 个指标 188 ns,读全部 1934 ns,ReadMemStats 22760 ns;读不存在的指标名返回 KindBad;并读 /sched/latencies 直方图。',
    'runtime.ReadMemStats 能读的东西有限,而且读一次要 2 万多纳秒。runtime/metrics 是更稳定的替代:每个指标一个字符串键,可以只读你要的。这篇列出全部指标,和 MemStats 对账,量读取成本,并读了一个调度等待的直方图。',
    [('107', 'Go 1.27.1 里 metrics.All() 返回的指标数'), ('188 ns vs 22760 ns', '读 1 个指标与 runtime.ReadMemStats 的单次耗时'), ('66 vs 51', '/sched/goroutines 指标与 NumGoroutine 的差:前者包含系统 goroutine')],
    [('指标清单', '<p>107 个指标里 /godebug 占 41 个(每个 GODEBUG 设置一个计数器),/gc 26 个,/memory 14 个,/sched 13 个。值类型只有三种:uint64、float64 和直方图。指标名里带单位(冒号后面),单位变了就是新的键。</p>'),
     ('读错名字不会崩', '<p>读一个不存在的指标得到 <code>KindBad</code>,同一次 <code>Read</code> 里其它指标正常。所以升级 Go 版本后某个指标被删了,你的程序不会 panic,但如果不检查 <code>Kind</code>,就会读到 0。</p>'),
     ('和 MemStats 对得上,除了 goroutine 数', '<p>分配字节数、对象数、GC 次数、Sys 都与 <code>MemStats</code> 完全一致。goroutine 数不一致不是 bug:源码里 <code>NumGoroutine</code> 调的是 <code>gcount(false)</code>(不含系统 goroutine),指标用的是 <code>gcount(true)</code>。这 15 个差值是系统 goroutine,我是从两处源码推出来的,没有逐个列举它们。</p>'),
     ('读起来便宜', '<p>复用同一个 <code>[]Sample</code>,读 1 个指标 188 ns,读全部 107 个 1934 ns,都没有分配;<code>ReadMemStats</code> 要 22760 ns。需要周期性采样时更适合 metrics。(这里只比较了耗时,没有测它们对其它 goroutine 的影响。)</p>'),
     ('直方图', '<p>调度等待的直方图有 162 个桶,累计型。在只有一个 P、200 个 goroutine 同时就绪的场景下,等待时间从几十毫秒到约 200 毫秒。只记录了 23 次,而不是 200 次;为什么我没有查,可能是采样,没有验证。要用它算百分位,需要自己遍历桶,上面是我的做法。</p>'),
     ('文档里的约定', '<p>指标的 kind 保证不变、浮点值不会出现 NaN 和无穷大;但指标本身可能被弃用和删除,文档建议对 <code>All</code> 返回的全部指标采样以保持兼容。</p>')],
    steps,
    [ENV_G + '。指标个数与分类来自 metrics.All();对账用同一个进程里连续读 MemStats 与 metrics(分配 100 个 1MiB 切片并 GC);成本用 testing.Benchmark;直方图实验用 GOMAXPROCS=1;读过的文档与源码:go doc runtime/metrics,runtime/debug.go 的 NumGoroutine,runtime/metrics.go 里 gTotal 的计算',
     '没有验证:系统 goroutine 具体是哪些、直方图只记录 23 次的原因、各指标在 Linux 上的取值差异、读指标对应用的干扰、/godebug 计数器的实际用法、长时间采样的开销'],
    'runtime/metrics')
